// Prefer LibraryImport for new code — trim and AOT friendly

internal static partial class Posix
{
    [LibraryImport("libc", StringMarshalling = StringMarshalling.Utf8)]
    internal static partial int gethostname(Span<byte> name, int len);

    public static string GetHostName()
    {
        Span<byte> buf = stackalloc byte[256];
        var rc = gethostname(buf, buf.Length);
        if (rc != 0) throw new InvalidOperationException("gethostname failed");
        return Encoding.UTF8.GetString(buf.Slice(0, buf.IndexOf((byte)0)));
    }
}

